import{_ as r,y as n,a as s,o as d,a2 as e,D as o}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"Payment Methods","description":"","frontmatter":{},"headers":[],"relativePath":"payment-method/payment-methods.md","filePath":"payment-method/payment-methods.md","lastUpdated":1789441803000}'),i={name:"payment-method/payment-methods.md"};function h(l,t,c,p,y,g){const a=n("ImagePopup");return d(),s("div",null,[t[0]||(t[0]=e('<h1 id="payment-methods" tabindex="-1">Payment Methods <a class="header-anchor" href="#payment-methods" aria-label="Permalink to &quot;Payment Methods&quot;">​</a></h1><p>Payment methods are the ways shoppers can pay at checkout. Bagisto comes with nine, and each has its own section under <strong>Configure &gt;&gt; Sales &gt;&gt; Payment Methods</strong>, in the order below.</p><table tabindex="0"><thead><tr><th>Method</th><th>How shoppers pay</th><th>What you need</th></tr></thead><tbody><tr><td><a href="#stripe">Stripe</a></td><td>By card, on Stripe&#39;s payment page</td><td>Stripe secret and publishable keys</td></tr><tr><td><a href="#razorpay">Razorpay</a></td><td>In a Razorpay payment window</td><td>Razorpay client ID and secret, and INR as your base currency</td></tr><tr><td><a href="#payu">PayU</a></td><td>On PayU&#39;s payment page</td><td>PayU merchant key and salt, and INR as your base currency</td></tr><tr><td><a href="#phonepe">PhonePe</a></td><td>On PhonePe&#39;s payment page</td><td>PhonePe client ID, client secret and merchant ID, and INR as your base currency</td></tr><tr><td><a href="#paypal">PayPal</a></td><td>With PayPal&#39;s buttons on the checkout page</td><td>The client ID and secret of a PayPal app</td></tr><tr><td><a href="#paypal-standard">PayPal Standard</a></td><td>On PayPal&#39;s website</td><td>The email address of a PayPal business account</td></tr><tr><td><a href="#payglocal">PayGlocal</a></td><td>On PayGlocal&#39;s payment page</td><td>A PayGlocal merchant ID, key IDs and key files</td></tr><tr><td><a href="#cash-on-delivery">Cash On Delivery</a></td><td>In cash when the order arrives</td><td>Nothing extra. It&#39;s offered only for carts of shippable products.</td></tr><tr><td><a href="#money-transfer">Money Transfer</a></td><td>By bank transfer or cheque</td><td>The name and address payments are sent to</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Switch off the methods you haven&#39;t set up</p><p>In a new store, <strong>Status</strong> is on for all nine methods. Stripe, Razorpay, PayU, PhonePe and PayGlocal come with placeholder keys, so they appear at checkout and fail when a shopper tries to pay. Before you take orders, switch off every method you haven&#39;t set up with your own credentials.</p></div><h2 id="offer-a-payment-method" tabindex="-1">Offer a payment method <a class="header-anchor" href="#offer-a-payment-method" aria-label="Permalink to &quot;Offer a payment method&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Payment Methods</strong>.</li><li>If your store has more than one channel or language, choose them at the top of the screen.</li><li>In the method&#39;s section, switch <strong>Status</strong> on. The method&#39;s other settings appear.</li><li>Enter the <strong>Title</strong> shoppers see at checkout.</li><li>Optionally, enter a <strong>Description</strong>.</li><li>Optionally, click <strong>Add Image</strong> under <strong>Logo</strong> and choose the logo.</li><li>Enter the settings of that method, described in its section below.</li><li>Enter the <strong>Sort Order</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>To stop offering a method, switch its <strong>Status</strong> off and save. At least one payment method has to stay on: saving with all of them switched off shows <strong>Enable at least one payment method.</strong></p><h3 id="settings-every-method-has" tabindex="-1">Settings every method has <a class="header-anchor" href="#settings-every-method-has" aria-label="Permalink to &quot;Settings every method has&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Status</strong></td><td>Offers the method at checkout. The other settings appear only while it&#39;s on.</td></tr><tr><td><strong>Title</strong></td><td>The name of the method at checkout. Required while <strong>Status</strong> is on.</td></tr><tr><td><strong>Description</strong></td><td>A short line shown under the title at checkout.</td></tr><tr><td><strong>Logo</strong></td><td>The logo on the method&#39;s card at checkout. Without one, Bagisto shows its built-in logo for the method. A size of 55 × 45 pixels is recommended.</td></tr><tr><td><strong>Sort Order</strong></td><td>The position of the method at checkout. Methods with a lower number come first. Required while <strong>Status</strong> is on.</td></tr></tbody></table><p>At checkout, shoppers see each method you offer as a card with its title and description, in sort order.</p>',10)),o(a,{src:"/images/configure/payment-methods-checkout.png",alt:"Payment methods offered as cards on the storefront checkout page"}),t[1]||(t[1]=e('<p>All settings are per channel. <strong>Title</strong>, <strong>Description</strong> and the Cash On Delivery <strong>Instructions</strong> are also per language.</p><h3 id="sandbox-mode" tabindex="-1">Sandbox mode <a class="header-anchor" href="#sandbox-mode" aria-label="Permalink to &quot;Sandbox mode&quot;">​</a></h3><p>Every method except Cash On Delivery and Money Transfer has a <strong>Sandbox</strong> switch, and it&#39;s on in a new store. While it&#39;s on, payments go to the gateway&#39;s test environment, so no real money is taken. Stripe and Razorpay have separate fields for test keys, which are used while <strong>Sandbox</strong> is on. The other gateways use the same credential fields in both modes, so enter the test credentials the gateway gives you while you test, and your live credentials when you switch <strong>Sandbox</strong> off.</p><h3 id="what-happens-when-a-shopper-pays-online" tabindex="-1">What happens when a shopper pays online <a class="header-anchor" href="#what-happens-when-a-shopper-pays-online" aria-label="Permalink to &quot;What happens when a shopper pays online&quot;">​</a></h3><p>With Stripe, Razorpay, PayU, PhonePe, PayPal and PayGlocal, the order is created once the gateway confirms the payment. It&#39;s invoiced automatically and set to <strong>Processing</strong>, or to <strong>Completed</strong> when nothing in it needs shipping. If the shopper cancels or the payment fails, they return to the cart. With PayPal, a shopper who closes the PayPal window stays on the checkout page and can try again. PayPal Standard works differently; see <a href="#paypal-standard">PayPal Standard</a>.</p><h2 id="stripe" tabindex="-1">Stripe <a class="header-anchor" href="#stripe" aria-label="Permalink to &quot;Stripe&quot;">​</a></h2><p>Stripe takes card payments. After clicking <strong>Place Order</strong>, shoppers pay on Stripe&#39;s secure payment page and return to the store.</p>',7)),o(a,{src:"/images/configure/payment-stripe.png",alt:"Stripe section with Status and Sandbox switched on"}),t[2]||(t[2]=e('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>API Key</strong></td><td>The live secret key from your Stripe account, used while <strong>Sandbox</strong> is off.</td></tr><tr><td><strong>API Publishable Key</strong></td><td>The live publishable key from your Stripe account, used while <strong>Sandbox</strong> is off.</td></tr><tr><td><strong>Sandbox</strong></td><td>Uses the test keys below, so no real payments are taken.</td></tr><tr><td><strong>API Test Secret Key</strong></td><td>The test secret key from your Stripe account, used while <strong>Sandbox</strong> is on.</td></tr><tr><td><strong>API Test Publishable Key</strong></td><td>The test publishable key from your Stripe account, used while <strong>Sandbox</strong> is on.</td></tr></tbody></table><p>Stripe appears at checkout only while both keys for the current mode have a value.</p><h2 id="razorpay" tabindex="-1">Razorpay <a class="header-anchor" href="#razorpay" aria-label="Permalink to &quot;Razorpay&quot;">​</a></h2><p>Razorpay takes payments in Indian rupees. After clicking <strong>Place Order</strong>, shoppers pay in a Razorpay payment window. If your store&#39;s base currency isn&#39;t <strong>INR</strong>, switch Razorpay off: it still shows at checkout, but the order can&#39;t be placed with it.</p>',4)),o(a,{src:"/images/configure/payment-razorpay.png",alt:"Razorpay section with Status and Sandbox switched on"}),t[3]||(t[3]=e('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Merchant Name</strong></td><td>Your business name, shown in the Razorpay payment window. Up to 200 characters.</td></tr><tr><td><strong>Merchant Description</strong></td><td>A short description shown in the payment window. Up to 200 characters.</td></tr><tr><td><strong>Client ID</strong> and <strong>Client Secret</strong></td><td>Your live API keys from Razorpay, used while <strong>Sandbox</strong> is off.</td></tr><tr><td><strong>Sandbox</strong></td><td>Uses the test keys below, so no real payments are taken.</td></tr><tr><td><strong>Test Mode Client ID</strong> and <strong>Test Mode Client Secret</strong></td><td>Your test API keys from Razorpay, used while <strong>Sandbox</strong> is on.</td></tr></tbody></table><p>Razorpay appears at checkout only while the client ID and secret for the current mode have a value: the test pair while <strong>Sandbox</strong> is on, the live pair while it&#39;s off.</p><h2 id="payu" tabindex="-1">PayU <a class="header-anchor" href="#payu" aria-label="Permalink to &quot;PayU&quot;">​</a></h2><p>PayU takes payments in Indian rupees. After clicking <strong>Place Order</strong>, shoppers are taken to PayU to pay. If your store&#39;s base currency isn&#39;t <strong>INR</strong>, switch PayU off: it still shows at checkout, but the order can&#39;t be placed with it.</p>',4)),o(a,{src:"/images/configure/payment-payu.png",alt:"PayU section with Status and Sandbox switched on"}),t[4]||(t[4]=e('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Merchant Key</strong></td><td>The merchant key from your PayU dashboard.</td></tr><tr><td><strong>Merchant Salt</strong></td><td>The merchant salt from your PayU dashboard.</td></tr><tr><td><strong>Sandbox</strong></td><td>Sends payments to PayU&#39;s test environment.</td></tr></tbody></table><p>PayU appears at checkout only while <strong>Merchant Key</strong> and <strong>Merchant Salt</strong> have a value.</p><h2 id="phonepe" tabindex="-1">PhonePe <a class="header-anchor" href="#phonepe" aria-label="Permalink to &quot;PhonePe&quot;">​</a></h2><p>PhonePe takes payments in Indian rupees. After clicking <strong>Place Order</strong>, shoppers are taken to PhonePe to pay. If your store&#39;s base currency isn&#39;t <strong>INR</strong>, switch PhonePe off: it still shows at checkout, but the order can&#39;t be placed with it.</p>',4)),o(a,{src:"/images/configure/payment-phonepe.png",alt:"PhonePe section with Status and Sandbox switched on"}),t[5]||(t[5]=e('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Client ID</strong></td><td>The client ID from your PhonePe dashboard. Required while <strong>Status</strong> is on.</td></tr><tr><td><strong>Client Secret</strong></td><td>The client secret from your PhonePe dashboard. Required while <strong>Status</strong> is on.</td></tr><tr><td><strong>Merchant ID</strong></td><td>The merchant ID from your PhonePe dashboard. Required while <strong>Status</strong> is on.</td></tr><tr><td><strong>Sandbox</strong></td><td>Sends payments to PhonePe&#39;s test environment.</td></tr></tbody></table><h2 id="paypal" tabindex="-1">PayPal <a class="header-anchor" href="#paypal" aria-label="Permalink to &quot;PayPal&quot;">​</a></h2><p>PayPal shows PayPal&#39;s own payment buttons on the checkout page in place of <strong>Place Order</strong>, so shoppers can pay without leaving the store. Which ways to pay the buttons offer, such as a PayPal account or a card, is decided by PayPal.</p>',3)),o(a,{src:"/images/configure/payment-paypal.png",alt:"PayPal section with Status and Sandbox switched on"}),t[6]||(t[6]=e('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Client ID</strong></td><td>The client ID of your PayPal app. While <strong>Sandbox</strong> is on, use the client ID of your sandbox app.</td></tr><tr><td><strong>Client Secret</strong></td><td>The client secret of your PayPal app.</td></tr><tr><td><strong>Accepted currencies</strong></td><td>The currency codes your PayPal account accepts, separated by commas, such as <code>USD,EUR</code>. List every currency your shoppers can pay in.</td></tr><tr><td><strong>Sandbox</strong></td><td>Sends payments to PayPal&#39;s sandbox, so no real payments are taken.</td></tr></tbody></table><h2 id="paypal-standard" tabindex="-1">PayPal Standard <a class="header-anchor" href="#paypal-standard" aria-label="Permalink to &quot;PayPal Standard&quot;">​</a></h2><p>PayPal Standard sends shoppers to PayPal&#39;s website to pay, and brings them back to the store afterwards. The order is created as <strong>Pending</strong> when the shopper returns. It&#39;s invoiced and moves to <strong>Processing</strong> once PayPal confirms to the store a payment that matches the order total.</p>',3)),o(a,{src:"/images/configure/payment-paypal-standard.png",alt:"PayPal Standard section with Status and Sandbox switched on"}),t[7]||(t[7]=e('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Business Account</strong></td><td>The email address of your PayPal business account. Required while <strong>Status</strong> is on.</td></tr><tr><td><strong>Sandbox</strong></td><td>Sends payments to PayPal&#39;s sandbox, so no real payments are taken.</td></tr></tbody></table><h2 id="payglocal" tabindex="-1">PayGlocal <a class="header-anchor" href="#payglocal" aria-label="Permalink to &quot;PayGlocal&quot;">​</a></h2><p>PayGlocal takes cross-border payments. After clicking <strong>Place Order</strong>, shoppers pay on PayGlocal&#39;s payment page and return to the store. The link in the section&#39;s description takes you to PayGlocal to sign up and get your credentials.</p>',3)),o(a,{src:"/images/configure/payment-payglocal.png",alt:"PayGlocal section with Status and Sandbox switched on"}),t[8]||(t[8]=e('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Merchant ID</strong></td><td>Your merchant ID, found under <strong>My Account</strong> in the PayGlocal dashboard.</td></tr><tr><td><strong>Public Key ID</strong></td><td>The ID of the PayGlocal public key, shown in the PayGlocal dashboard.</td></tr><tr><td><strong>Private Key ID</strong></td><td>The ID of your private key, shown in the PayGlocal dashboard.</td></tr><tr><td><strong>PayGlocal Public Key</strong></td><td>The contents of the PayGlocal public key file.</td></tr><tr><td><strong>Merchant Private Key</strong></td><td>The contents of the private key file you generated in the PayGlocal dashboard.</td></tr><tr><td><strong>Accepted currencies</strong></td><td>The currency codes your PayGlocal account accepts, separated by commas, such as <code>USD,INR</code>. Include your store&#39;s base currency. Required while <strong>Status</strong> is on.</td></tr><tr><td><strong>Sandbox</strong></td><td>Sends payments to PayGlocal&#39;s test environment.</td></tr></tbody></table><p>PayGlocal appears at checkout only while the <strong>Merchant ID</strong>, both key IDs and both keys have a value. The keys aren&#39;t checked when you save, so test a payment in sandbox mode before you go live.</p><h2 id="cash-on-delivery" tabindex="-1">Cash On Delivery <a class="header-anchor" href="#cash-on-delivery" aria-label="Permalink to &quot;Cash On Delivery&quot;">​</a></h2><p>Cash On Delivery lets shoppers pay in cash when the order arrives. It&#39;s offered only when every product in the cart is shipped, so it doesn&#39;t appear for carts with virtual, downloadable or booking products.</p>',4)),o(a,{src:"/images/configure/payment-cash-on-delivery.png",alt:"Cash On Delivery section with Status and automatic invoicing switched on"}),t[9]||(t[9]=e('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Instructions</strong></td><td>Instructions for the customer, such as having the exact amount ready. They are included in the order emails and on the invoice PDF.</td></tr><tr><td><strong>Automatically generate the invoice after placing an order</strong></td><td>Creates the invoice as soon as the order is placed.</td></tr><tr><td><strong>Set the invoice status after creating the invoice to</strong></td><td><strong>Pending</strong> or <strong>Paid</strong>. Used only while the switch above is on.</td></tr><tr><td><strong>Set the order status after creating the invoice to</strong></td><td><strong>Pending</strong>, <strong>Pending Payment</strong> or <strong>Processing</strong>. Used only while the switch above is on.</td></tr></tbody></table><h2 id="money-transfer" tabindex="-1">Money Transfer <a class="header-anchor" href="#money-transfer" aria-label="Permalink to &quot;Money Transfer&quot;">​</a></h2><p>Money Transfer lets shoppers pay by bank transfer or cheque.</p>',3)),o(a,{src:"/images/configure/payment-money-transfer.png",alt:"Money Transfer section with Status and automatic invoicing switched on"}),t[10]||(t[10]=e('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Automatically generate the invoice after placing an order</strong></td><td>Creates the invoice as soon as the order is placed.</td></tr><tr><td><strong>Set the invoice status after creating the invoice to</strong></td><td><strong>Pending</strong> or <strong>Paid</strong>. Used only while the switch above is on.</td></tr><tr><td><strong>Set the order status after creating the invoice to</strong></td><td><strong>Pending</strong>, <strong>Pending Payment</strong> or <strong>Processing</strong>. Used only while the switch above is on.</td></tr><tr><td><strong>Send Check to</strong></td><td>The name and address customers send their payment to. It&#39;s included in the order emails and on the invoice PDF.</td></tr></tbody></table><p>For orders you take yourself in the admin panel, see <a href="./../orders/create-order.html">Create Order</a>. To create an invoice later, see <a href="./../orders/create-invoice.html">Create Invoice</a>. What each invoice status means is described in <a href="./../orders/create-invoice.html#invoice-status">Invoice status</a>, and payments for pending invoices are recorded in <a href="./../orders/transactions.html">Transactions</a>.</p>',2))])}const P=r(i,[["render",h]]);export{m as __pageData,P as default};
